export function ParallaxZoomDemo() {
  const wrapperRef = useRef<HTMLDivElement>(null);
  const containerRef = useRef<HTMLDivElement>(null);

  useGSAP(() => {
    const els = gsap.utils.toArray<HTMLElement>(".el");
    els.forEach((el, index) => {
      gsap.fromTo(el, { scale: 1 }, {
        scale: pictures[index].scale,
        scrollTrigger: { trigger: containerRef.current, scrub: true }
      });
    });
  }, { scope: containerRef });

  return (
    <div ref={wrapperRef} className="overflow-y-auto">
      <div ref={containerRef} className="h-[300vh] relative">
        <div className="sticky top-0 h-screen overflow-hidden">
          {pictures.map((img, i) => (<div className="el">...</div>))}
        </div>
      </div>
    </div>
  );
}
